import React from 'react';

const recruiters = [
    { name: "TCS", logo: "https://logo.clearbit.com/tcs.com" },
    { name: "Infosys", logo: "https://logo.clearbit.com/infosys.com" },
    { name: "Wipro", logo: "https://logo.clearbit.com/wipro.com" },
    { name: "Cognizant", logo: "https://logo.clearbit.com/cognizant.com" },
    { name: "Accenture", logo: "https://logo.clearbit.com/accenture.com" },
    { name: "IBM", logo: "https://logo.clearbit.com/ibm.com" },
    { name: "L&T", logo: "https://logo.clearbit.com/larsentoubro.com" },
    { name: "Amazon", logo: "https://logo.clearbit.com/amazon.com" },
    { name: "Oracle", logo: "https://logo.clearbit.com/oracle.com" },
    { name: "Cisco", logo: "https://logo.clearbit.com/cisco.com" }
];

const Placement = () => {
    return (
        <section id="placement" className="py-16 bg-slate-50/50">
            <div className="max-w-[95%] mx-auto px-4 lg:px-6">
                <div className="mb-12 text-center">
                    <h2 className="text-[2.25rem] font-display font-black text-slate-800 mb-4 uppercase tracking-tight">
                        Training & Placement <span className="text-coral">Cell</span>
                    </h2>
                    <div className="w-24 h-1.5 bg-coral mx-auto rounded-full"></div>
                </div>

                <div className="bg-white border border-slate-200 rounded-2xl p-8 md:p-12 relative overflow-hidden shadow-[0_4px_20px_rgba(0,0,0,0.03)]">
                    <h3 className="text-xl font-bold text-slate-700 text-center mb-10 uppercase tracking-widest flex items-center justify-center gap-4">
                        <span className="h-px w-8 bg-slate-200 hidden sm:block"></span>
                        Our Major Recruiters
                        <span className="h-px w-8 bg-slate-200 hidden sm:block"></span>
                    </h3>

                    <style>
                    {`
                    @keyframes slide {
                        0% { transform: translateX(0); }
                        100% { transform: translateX(calc(-160px * 10)); }
                    }
                    .recruiters-track {
                        animation: slide 40s linear infinite;
                    }
                    .recruiters-track:hover {
                        animation-play-state: paused;
                    }
                    `}
                    </style>

                    <div className="flex overflow-hidden relative after:absolute after:right-0 after:top-0 after:h-full after:w-20 after:bg-gradient-to-l after:from-white after:to-transparent before:absolute before:left-0 before:top-0 before:h-full before:w-20 before:bg-gradient-to-r before:from-white before:to-transparent before:z-10 after:z-10">
                        <div className="flex gap-8 recruiters-track items-center min-w-max py-4">
                            {[...recruiters, ...recruiters].map((rec, idx) => (
                                <div key={idx} className="group w-40 h-20 bg-white flex items-center justify-center rounded-xl border border-slate-100 shadow-sm hover:border-coral/30 hover:shadow-md transition-all duration-300 px-6">
                                    <img 
                                        src={rec.logo} 
                                        alt={rec.name} 
                                        className="max-w-full max-h-[70%] object-contain grayscale opacity-60 group-hover:grayscale-0 group-hover:opacity-100 transition-all duration-500 scale-95 group-hover:scale-105"
                                        onError={(e) => {
                                            e.target.onerror = null;
                                            e.target.style.display = 'none';
                                            e.target.nextSibling.style.display = 'block';
                                        }}
                                    />
                                    <span className="hidden font-bold text-slate-500 text-sm tracking-wide uppercase">{rec.name}</span>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="mt-10 grid grid-cols-2 md:grid-cols-4 gap-6 text-center border-t border-slate-200 pt-8">
                        <div>
                            <div className="text-[2rem] font-bold text-coral mb-1">450+</div>
                            <div className="text-[1rem] font-bold text-slate-500 uppercase tracking-wider">Offers in 2024</div>
                        </div>
                        <div>
                            <div className="text-[2rem] font-bold text-coral mb-1">60+</div>
                            <div className="text-[1rem] font-bold text-slate-500 uppercase tracking-wider">Companies Visited</div>
                        </div>
                        <div>
                            <div className="text-[2rem] font-bold text-coral mb-1">14 LPA</div>
                            <div className="text-[1rem] font-bold text-slate-500 uppercase tracking-wider">Highest Package</div>
                        </div>
                        <div>
                            <div className="text-[2rem] font-bold text-coral mb-1">90%</div>
                            <div className="text-[1rem] font-bold text-slate-500 uppercase tracking-wider">Placement Record</div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default Placement;
